export const GROOVE_COUNT = GROOVES.length;

const wrapIndex = (index) => ((Math.trunc(index) % GROOVE_COUNT) + GROOVE_COUNT) % GROOVE_COUNT;
export const grooveAt = (index) => GROOVES[wrapIndex(index)];
export const stepGroove = (index, direction) => wrapIndex(index + Math.sign(direction));

/** Every hit in one bar, step-sorted so a scheduler can walk it forward. */
export function grooveHits(groove) {
  const hits = [];
  for (const part of Object.keys(groove.parts)) {
    for (const hit of parseStepPattern(groove.parts[part])) {
      hits.push({ step: hit.step, part, vel: hit.vel });
    }
  }
  hits.sort((a, b) => a.step - b.step);
  return hits;
}

export const grooveDensity = (groove) => grooveHits(groove).length;

// ============================================================
// TEMPO AND TIME
// ============================================================
export const TEMPO_MIN = 60;
export const TEMPO_MAX = 160;
export const TEMPO_STEP = 4;
export const TEMPO_DEFAULT = 92;

export function stepTempo(bpm, direction) {
  const next = Math.round(bpm / TEMPO_STEP) * TEMPO_STEP + Math.sign(direction) * TEMPO_STEP;
  return Math.max(TEMPO_MIN, Math.min(TEMPO_MAX, next));
}

export const barSeconds = (bpm, beats = 4) => (beats * 60) / bpm;
export const stepSeconds = (bpm, groove) => barSeconds(bpm, groove.beats) / groove.steps;
export const stepTime = (groove, bpm, bar, step) =>
  bar * barSeconds(bpm, groove.beats) + step * stepSeconds(bpm, groove);

/** Step 0 sits at 12 o'clock, like the tonic on the chord wheel. */
export const stepAngle = (step, steps) => (step / steps) * 360;

/**
 * How many whole bars a take of `seconds` meant. Rounds to nearest, not up: a
 * finger that lifts a hair early meant this bar, and ceiling would hand back a
 * bar of silence.
 */
export function barsForDuration(seconds, bpm, groove, maxSeconds) {
  const bar = barSeconds(bpm, groove.beats);
  const maxBars = Math.max(1, Math.floor(maxSeconds / bar));
  return Math.min(maxBars, Math.max(1, Math.round(seconds / bar)));
}

// ============================================================
// HOW HARD A HIT LANDS
// A drum hit is a tap, so there is no stroke speed to read the way a strum has
// one. What a tap does carry is *where on the head it landed* — centre loud,
// rim quiet, which is the one dynamic a fingertip can genuinely express — and,
// when the finger is dragging across the kit, how fast it is travelling.
// Never returns zero: a rim shot is quiet, not silent.
// ============================================================
export const DRUM_VEL_MIN = 0.34;

export function drumHitVelocity({ radiusFraction = 0, speedPxPerMs = null } = {}) {
  const place = Math.max(0, Math.min(1, radiusFraction));
  const byPlace = 1 - place * 0.55;
  const bySpeed = speedPxPerMs === null ? 1 : Math.min(1, 0.55 + speedPxPerMs * 0.6);
  return Math.max(DRUM_VEL_MIN, Math.min(1, byPlace * bySpeed));
}
